	defer f.mu.Unlock()
	f.failure = failure
	f.objects = make(map[string]map[string][]byte)
	f.channelWrites = make(map[string]int)
	f.binaryCreates = make(map[string]int)
	f.inspections.Store(0)
}

func newApplyHTTPFixture(t *testing.T) *applyHTTPFixture {
	t.Helper()
